package com.shortlinkx.service;
import com.shortlinkx.dto.AnalyticsResponse;import com.shortlinkx.repository.*;import org.springframework.stereotype.Service;import java.util.*;
@Service public class AnalyticsService{private final ClickEventRepository clicks;private final ShortUrlRepository urls;public AnalyticsService(ClickEventRepository clicks,ShortUrlRepository urls){this.clicks=clicks;this.urls=urls;}public AnalyticsResponse get(String code){urls.findByShortCode(code).orElseThrow(()->new IllegalArgumentException("Short URL not found."));var recent=clicks.findTop100ByShortCodeOrderByClickedAtDesc(code).stream().map(e->new AnalyticsResponse.ClickSummary(e.getClickedAt(),e.getDevice(),e.getBrowser(),e.getOperatingSystem())).toList();return new AnalyticsResponse(code,clicks.countByShortCode(code),recent);}}
